      "dis_quote": "과정부터 전공과정까지 발달장애 학생을 위한 교육과정을 운영하는 공립 특수학교입니다. 우리 학교는 ‘열심히 배우고 익혀 스스로 생활하자.’ 라는 교훈을 마음에 새기며, 학생 한 명 한 명의 소중한 가능성",
