      "stage_quote": "환영합니다. 서울경운학교는 초등학교 과정부터 전공과정까지 발달장애 학생을 위한 교육과정을 운영하는 공립 특수학교입니다. 우리 학교는 ‘열심히 배우고 익혀 스스로 생활하자.’ 라는 교훈을 마음에 새기며, 학생 한 명 한 명의 소중한 가능성을 발견하고 행복한 성장을 돕기 위해 함께하고 있습니다. 우리의 교훈에는 학생들이 자신의 가능성을 믿고, 배움과 다양한 경험을 통해 조금씩 성장하며, 자신의 삶을 스스로 선택하고 살아갈 수 있기를 바라는 마음이 담겨 있습니다. 서울",
      "stage_url": "https://gyeongun.sen.sc.kr/11650/subMenu.do",
